Now moving to Phase 2: Profile API Routes & Services. I'll create the profile queries first:

<write_to_file>
<path>apps/api/src/db/profileQueries.ts</path>
<content>import Database from "better-sqlite3";
import type { Profile, CreateProfileInput, UpdateProfileInput } from "@snake/contracts";

const dbPath = process.env.DB_PATH || "./data/snake.db";
const db = new Database(dbPath);

export const profileQueries = {
  listProfiles(): Profile[] {
    const stmt = db.prepare(`
      SELECT id, name, avatar_base64 as avatarBase64, created_at as createdAt, 
             updated_at as updatedAt, is_active as isActive
      FROM profiles
      ORDER BY created_at DESC
    `);

    const rows = stmt.all() as Array<{
      id: string;
      name: string;
      avatarBase64: string | null;
      createdAt: string;
      updatedAt: string;
      isActive: number;
    }>;

    return rows.map(row => ({
      ...row,
      avatarBase64: row.avatarBase64 || null,
      isActive: row.isActive === 1
    }));
  },

  getProfile(id: string): Profile | null {
    const stmt = db.prepare(`
      SELECT id, name, avatar_base64 as avatarBase64, created_at as createdAt, 
             updated_at as updatedAt, is_active as isActive
      FROM profiles
      WHERE id = ?
    `);

    const row = stmt.get(id) as {
      id: string;
      name: string;
      avatarBase64: string | null;
      createdAt: string;
      updatedAt: string;
      isActive: number;
    } | undefined;

    if (!row) return null;

    return {
      ...row,
      avatarBase64: row.avatarBase64 || null,
      isActive: row.isActive === 1
    };
  },

  getActiveProfile(): Profile | null {
    const stmt = db.prepare(`
      SELECT id, name, avatar_base64 as avatarBase64, created_at as createdAt, 
             updated_at as updatedAt, is_active as isActive
      FROM profiles
      WHERE is_active = 1
      LIMIT 1
    `);

    const row = stmt.get() as {
      id: string;
      name: string;
      avatarBase64: string | null;
      createdAt: string;
      updatedAt: string;
      isActive: number;
    } | undefined;

    if (!row) return null;

    return {
      ...row,
      avatarBase64: row.avatarBase64 || null,
      isActive: row.isActive === 1
    };
  },

  createProfile(input: CreateProfileInput): Profile {
    const id = crypto.randomUUID();
    const now = new Date().toISOString();

    // Check if this is the first profile
    const countStmt = db.prepare("SELECT COUNT(*) as count FROM profiles");
    const { count } = countStmt.get() as { count: number };
    const isActive = count === 0 ? 1 : 0; // Auto-activate if first profile

    const stmt = db.prepare(`
      INSERT INTO profiles (id, name, avatar_base64, created_at, updated_at, is_active)
      VALUES (?, ?, ?, ?, ?, ?)
    `);

    stmt.run(id, input.name, input.avatarBase64 || null, now, now, isActive);

    return {
      id,
      name: input.name,
      avatarBase64: input.avatarBase64 || null,
      createdAt: now,
      updatedAt: now,
      isActive: isActive === 1
    };
  },

  updateProfile(id: string, input: UpdateProfileInput): Profile | null {
    const existing = this.getProfile(id);
    if (!existing) return null;

    const now = new Date().toISOString();
    const name = input.name ?? existing.name;
    const avatarBase64 = input.avatarBase64 !== undefined ? input.avatarBase64 : existing.avatarBase64;

    const stmt = db.prepare(`
      UPDATE profiles
      SET name = ?, avatar_base64 = ?, updated_at = ?
      WHERE id = ?
    `);

    stmt.run(name, avatarBase64, now, id);

    return {
      ...existing,
      name,
      avatarBase64,
      updatedAt: now
    };
  },

  deleteProfile(id: string): boolean {
    const stmt = db.prepare("DELETE FROM profiles WHERE id = ?");
    const result = stmt.run(id);
    return result.changes > 0;
  },

  activateProfile(id: string): Profile | null {
    const profile = this.getProfile(id);
    if (!profile) return null;

    // Deactivate all profiles
    const deactivateStmt = db.prepare("UPDATE profiles SET is_active = 0");
    deactivateStmt.run();

    // Activate the specified profile
    const activateStmt = db.prepare("UPDATE profiles SET is_active = 1, updated_at = ? WHERE id = ?");
    const now = new Date().toISOString();
    activateStmt.run(now, id);

    return {
      ...profile,
      isActive: true,
      updatedAt: now
    };
  }
};
</content>
</write_to_file>

Now I'll create the profile data service:

<write_to_file>
<path>apps/api/src/services/profileDataService.ts</path>
<content>import {
  type Profile,
  type CreateProfileInput,
  type UpdateProfileInput,
  type ProfilesListResponse,
  type ProfileResponse,
  type ActiveProfileResponse
} from "@snake/contracts";
import { profileQueries } from "../db/profileQueries";

export const profileDataService = {
  listProfiles(): ProfilesListResponse {
    const profiles = profileQueries.listProfiles();
    return { profiles };
  },

  getProfile(id: string): ProfileResponse | null {
    const profile = profileQueries.getProfile(id);
    if (!profile) return null;
    return { profile };
  },

  getActiveProfile(): ActiveProfileResponse {
    const profile = profileQueries.getActiveProfile();
    return { profile };
  },

  createProfile(input: CreateProfileInput): ProfileResponse {
    const profile = profileQueries.createProfile(input);
    return { profile };
  },

  updateProfile(id: string, input: UpdateProfileInput): ProfileResponse | null {
    const profile = profileQueries.updateProfile(id, input);
    if (!profile) return null;
    return { profile };
  },

  deleteProfile(id: string): boolean {
    return profileQueries.deleteProfile(id);
  },

  activateProfile(id: string): ProfileResponse | null {
    const profile = profileQueries.activateProfile(id);
    if (!profile) return null;
    return { profile };
  }
};
</content>
</write_to_file>

Now I'll create the profile routes:

<write_to_file>
<path>apps/api/src/routes/profileRoutes.ts</path>
<content>import express from "express";
import {
  createProfileInputSchema,
  updateProfileInputSchema,
  profilesListResponseSchema,
  profileResponseSchema,
  activeProfileResponseSchema
} from "@snake/contracts";
import { profileDataService } from "../services/profileDataService";

const router = express.Router();

// GET /profiles - List all profiles
router.get("/", (req, res) => {
  try {
    const response = profileDataService.listProfiles();
    const validated = profilesListResponseSchema.parse(response);
    res.json(validated);
  } catch (error) {
    console.error("Error listing profiles:", error);
    res.status(500).json({ error: "Failed to list profiles" });
  }
});

// GET /profiles/active - Get active profile
router.get("/active", (req, res) => {
  try {
    const response = profileDataService.getActiveProfile();
    const validated = activeProfileResponseSchema.parse(response);
    res.json(validated);
  } catch (error) {
    console.error("Error getting active profile:", error);
    res.status(500).json({ error: "Failed to get active profile" });
  }
});

// GET /profiles/:id - Get one profile
router.get("/:id", (req, res) => {
  try {
    const { id } = req.params;
    const response = profileDataService.getProfile(id);

    if (!response) {
      res.status(404).json({ error: "Profile not found" });
      return;
    }

    const validated = profileResponseSchema.parse(response);
    res.json(validated);
  } catch (error) {
    console.error("Error getting profile:", error);
    res.status(500).json({ error: "Failed to get profile" });
  }
});

// POST /profiles - Create profile
router.post("/", (req, res) => {
  try {
    const input = createProfileInputSchema.parse(req.body);
    const response = profileDataService.createProfile(input);
    const validated = profileResponseSchema.parse(response);
    res.status(201).json(validated);
  } catch (error) {
    console.error("Error creating profile:", error);
    if (error instanceof Error && error.message.includes("parse")) {
      res.status(400).json({ error: "Invalid input" });
    } else {
      res.status(500).json({ error: "Failed to create profile" });
    }
  }
});

// PUT /profiles/:id - Update profile
router.put("/:id", (req, res) => {
  try {
    const { id } = req.params;
    const input = updateProfileInputSchema.parse(req.body);
    const response = profileDataService.updateProfile(id, input);

    if (!response) {
      res.status(404).json({ error: "Profile not found" });
      return;
    }

    const validated = profileResponseSchema.parse(response);
    res.json(validated);
  } catch (error) {
    console.error("Error updating profile:", error);
    if (error instanceof Error && error.message.includes("parse")) {
      res.status(400).json({ error: "Invalid input" });
    } else {
      res.status(500).json({ error: "Failed to update profile" });
    }
  }
});

// DELETE /profiles/:id - Delete profile
router.delete("/:id", (req, res) => {
  try {
    const { id } = req.params;
    const success = profileDataService.deleteProfile(id);

    if (!success) {
      res.status(404).json({ error: "Profile not found" });
      return;
    }

    res.status(204).send();
  } catch (error) {
    console.error("Error deleting profile:", error);
    res.status(500).json({ error: "Failed to delete profile" });
  }
});

// POST /profiles/:id/activate - Activate profile
router.post("/:id/activate", (req, res) => {
  try {
    const { id } = req.params;
    const response = profileDataService.activateProfile(id);

    if (!response) {
      res.status(404).json({ error: "Profile not found" });
      return;
    }

    const validated = profileResponseSchema.parse(response);
    res.json(validated);
  } catch (error) {
    console.error("Error activating profile:", error);
    res.status(500).json({ error: "Failed to activate profile" });
  }
});

export default router;
</content>
</write_to_file>

