<content>import type {
  Profile,
  CreateProfileInput,
  UpdateProfileInput,
  ProfilesListResponse,
  ProfileResponse,
  ActiveProfileResponse
} from "@snake/contracts";

export interface ProfileService {
  listProfiles(): Promise<ProfilesListResponse>;
