import { ScorePanel } from "../components/game/ScorePanel";
import { localGameService } from "../services/storage/localGameService";
import { apiGameService } from "../services/adapters/apiGameService";
import { useProfileContext } from "../contexts/ProfileContext";
import type { LeaderboardEntry } from "@snake/contracts";

const USE_API = import.meta.env.VITE_USE_API === "true";
const gameService = USE_API ? apiGameService : localGameService;

export const StatsPage = () => {
  const { activeProfile } = useProfileContext();
  const [currentTab, setCurrentTab] = useState(0);
  const [myScores, setMyScores] = useState<LeaderboardEntry[]>([]);
  const [globalScores, setGlobalScores] = useState<LeaderboardEntry[]>([]);
  const [highScore, setHighScore] = useState<number>(0);

  useEffect(() => {
    const loadStats = async () => {
      const [myLeaderboard, globalLeaderboard, highScoreData] = await Promise.all([
        gameService.getLeaderboard(10),
        gameService.getLeaderboardGlobal(10),
        gameService.getHighScore()
      ]);
      setMyScores(myLeaderboard.entries);
      setGlobalScores(globalLeaderboard.entries);
      setHighScore(highScoreData.highScore);
    };
    loadStats();
  }, []);

  return (
    <PageLayout>
      <Stack spacing={3}>
        <ScorePanel 
          player={activeProfile} 
          score={0} 
          highScore={highScore} 
          status="idle" 
        />

